HRESULT wxWebViewEdgeImpl::OnNavigationStarting(ICoreWebView2* WXUNUSED(sender), ICoreWebView2NavigationStartingEventArgs* args)
{
    return HandleNavigationStarting(args, true);
}

HRESULT wxWebViewEdgeImpl::OnFrameNavigationStarting(ICoreWebView2* WXUNUSED(sender), ICoreWebView2NavigationStartingEventArgs* args)
{
    return HandleNavigationStarting(args, false);
}

HRESULT wxWebViewEdgeImpl::HandleNavigationStarting(ICoreWebView2NavigationStartingEventArgs* args, bool mainFrame)
{
    wxWEBVIEW_EDGE_EVENT_HANDLER_METHOD
    m_isBusy = true;
    wxString evtURL;
    wxCoTaskMemPtr<wchar_t> uri;
    if (SUCCEEDED(args->get_Uri(&uri)))
        evtURL = wxString(uri);

    // Check if this is a custom scheme URL that needs translation
    // (e.g., memory:page2.htm -> https://memory.wxsite/page2.htm)
    for (const auto& kv : m_handlers)
    {
        const wxString scheme = kv.second->GetName() + ":";
        if (evtURL.StartsWith(scheme))
        {
            // Cancel this navigation and redirect through LoadURL
            // which will translate the custom scheme URL
            args->put_Cancel(true);
            m_ctrl->LoadURL(evtURL);
            return S_OK;
        }
    }

    wxWebViewEvent event(wxEVT_WEBVIEW_NAVIGATING, m_ctrl->GetId(), evtURL, wxString());
    event.SetEventObject(m_ctrl);
    if (mainFrame)
        event.SetInt(1);
    m_ctrl->HandleWindowEvent(event);

        wxWebViewEvent event(wxEVT_WEBVIEW_NAVIGATED,
                             webKitCtrl->GetId(),
                             url, target);
        event.SetEventObject(webKitCtrl);

        webKitCtrl->HandleWindowEvent(event);
    }
}

static gboolean
wxgtk_webview_webkit_navigation(WebKitWebView *,
                                WebKitPolicyDecision *decision,
                                wxWebViewWebKit *webKitCtrl)
{
    WebKitNavigationPolicyDecision* navigation_decision = WEBKIT_NAVIGATION_POLICY_DECISION(decision);
    WebKitNavigationAction* action = webkit_navigation_policy_decision_get_navigation_action(navigation_decision);
    WebKitURIRequest* request = webkit_navigation_action_get_request(action);
    const gchar* uri = webkit_uri_request_get_uri(request);

    wxGCC_WARNING_SUPPRESS(deprecated-declarations)
    wxString target = webkit_navigation_policy_decision_get_frame_name(navigation_decision);
    wxGCC_WARNING_RESTORE(deprecated-declarations)

