18	  const [height, setHeight] = useState<number | null>(null);
19	
20	  // The content can't report its height without scripts, so the page
21	  // measures it, again whenever the frame's width changes the wrapping.
22	  const measure = () => {
23	    const root = frame.current?.contentDocument?.documentElement;
24	    if (loaded.current && root)
